import{_ as t,o as r,c as o,a2 as n}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"Ceph Performance Meeting 2022-01-27","description":"","frontmatter":{"title":"Ceph Performance Meeting 2022-01-27","date":"2022-01-27T00:00:00.000Z","updated":"2022-02-03T00:00:00.000Z","tags":["Ceph 性能","RocksDB","Scrub 优化","性能测试","RBD"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2022/Ceph_Performance_Meeting_2022-01-27.md","filePath":"posts/2022/Ceph_Performance_Meeting_2022-01-27.md","lastUpdated":1780460162000}'),a={name:"posts/2022/Ceph_Performance_Meeting_2022-01-27.md"};function s(i,e,l,c,h,u){return r(),o("div",null,[...e[0]||(e[0]=[n('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="关键细节" tabindex="-1">关键细节 <a class="header-anchor" href="#关键细节" aria-label="Permalink to &quot;关键细节&quot;">​</a></h4><ul><li><strong>Ceph 性能动态</strong>：本周性能相关 Pull Request 活动相对平静。</li><li><strong>Ronin 的 PR</strong>：涉及 scrub 功能的优化，主要是调整 chunk 大小以优化 scrub 过程。</li><li><strong>Scrub Chunk Size</strong>：讨论了 scrub 过程中 chunk 大小的配置，建议根据 scrub 类型（深度或常规）调整 chunk 大小。</li><li><strong>Tracing 功能</strong>：讨论了将 tracing 功能默认编译进 Ceph 的 PR，尽管有轻微性能开销，但便于用户调试。</li><li><strong>RocksDB 的 TTL 和 Compaction</strong>：讨论了 RocksDB 中的 TTL 和 compaction 设置，特别是在大量插入和删除操作下的性能问题，建议通过调整 TTL 清理 tombstones。</li></ul><h4 id="讨论的主要议题" tabindex="-1">讨论的主要议题 <a class="header-anchor" href="#讨论的主要议题" aria-label="Permalink to &quot;讨论的主要议题&quot;">​</a></h4><ul><li><strong>Scrub 性能优化</strong>：通过调整 scrub chunk 大小优化性能，同时减少对客户端请求的影响。</li><li><strong>Tracing 功能集成</strong>：讨论了将 tracing 功能默认编译进 Ceph 的利弊，以及如何平衡性能开销和调试便利性。</li><li><strong>RocksDB 性能问题</strong>：深入讨论了 RocksDB 在处理大量数据插入和删除时的性能问题，特别是 tombstones 导致的性能退化，提出了通过 TTL 定期清理 tombstones 的解决方案。</li></ul><h4 id="决定的事项" tabindex="-1">决定的事项 <a class="header-anchor" href="#决定的事项" aria-label="Permalink to &quot;决定的事项&quot;">​</a></h4><ul><li><strong>Scrub Chunk Size 调整</strong>：决定区分 deep scrub 和 regular scrub 的 chunk 大小，并进行进一步测试以确保不会引入新的延迟问题。</li><li><strong>Tracing 功能默认编译</strong>：尽管存在轻微性能开销，但决定将 tracing 功能默认编译进 Ceph，以便用户在需要时启用。</li><li><strong>RocksDB 的 TTL 设置</strong>：决定尝试通过调整 TTL 定期清理 tombstones，以解决性能退化问题，并进行进一步的测试和验证。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li><strong>Scrub Chunk Size 测试</strong>：进行进一步的测试，确保调整后的 chunk 大小不会影响客户端请求的性能。</li><li><strong>Tracing 功能评估</strong>：评估 tracing 功能默认编译后的性能影响，并考虑是否需要进一步优化。</li><li><strong>RocksDB 的 TTL 和 Compaction 测试</strong>：在实际生产环境中测试调整 TTL 后的性能表现，并监控其对系统的影响。</li><li><strong>与 Spdb 合作</strong>：考虑与 Spdb 合作，评估其 RocksDB 替代方案在 Ceph 中的性能表现，特别是在处理大量数据插入和删除时的性能优化。</li></ul><h4 id="其他事项" tabindex="-1">其他事项 <a class="header-anchor" href="#其他事项" aria-label="Permalink to &quot;其他事项&quot;">​</a></h4><ul><li><strong>性能测试和优化</strong>：继续关注和优化 Ceph 在不同硬件配置下的性能表现，特别是在 AMD 和 Intel 节点上的性能对比。</li><li><strong>生产环境验证</strong>：在实际生产环境中验证各项优化措施的效果，并根据反馈进行调整。</li></ul>',11)])])}const p=t(a,[["render",s]]);export{d as __pageData,p as default};
